<template><div><h1>Lista de Usuários</h1><ul><mostratPoke v-for="poke in lista" :key="poke.name" :nome="poke.name" :link="poke.url"/></ul></div></template><script setup>import mostratPoke from './components/mostratPoke.vue'import{ ref} from 'vue'import axios from 'axios'const lista=ref([])const carregarDados=async ()=>{ try{ const resposta=await axios.get('https://pokeapi.co/api/v2/pokemon?limit=100&offset=0') lista.value=resposta.data.results} catch (erro){ console.error('Erro ao buscar dados:', erro)}}carregarDados()</script>